window.ATLAS_ITEMS=window.ATLAS_ITEMS||{};window.ATLAS_ITEMS[147]={"id":"147","numero":147,"titre":"Fièvre aiguë chez l'enfant et l'adulte","objectifs":[{"id":"147-1","rang":"A","rubrique":"Définition","titre":"Connaître la définition et mesure de la fièvre chez l'enfant et chez l'adulte","contenu":"<p>Chez l'<strong>adulte</strong>, la <span class=\"kw-clinique\">fièvre</span> est définie comme une <span class=\"kw-def\">élévation de la température centrale au-dessus des variations circadiennes normales</span>. La définition n'est pas consensuelle : on retient une <span class=\"kw-bio\">température</span> <span class=\"kw-chiffre\">≥ 38 °C le matin</span> ou <span class=\"kw-chiffre\">≥ 38,3 °C le soir</span>.</p>\n      <table >\n        <thead><tr><th>Terme</th><th>Définition</th></tr></thead>\n        <tbody>\n          <tr><td>Température normale</td><td><span class=\"kw-chiffre\">≤ 37,5 °C le matin</span> et <span class=\"kw-chiffre\">≤ 37,8 °C le soir</span> ; variations physiologiques selon l'âge, le sexe, le rythme nycthéméral et l'activité physique</td></tr>\n          <tr><td><span class=\"kw-def\">Fébricule</span></td><td><span class=\"kw-bio\">Température</span> entre <span class=\"kw-chiffre\">37,5 et 38 °C</span> ; terme imprécis</td></tr>\n          <tr><td><span class=\"kw-def\">Fièvre aiguë</span></td><td>Évolue depuis <span class=\"kw-chiffre\">moins de 5 jours</span> ; étiologies le plus souvent <span class=\"kw-etio\">infectieuses</span></td></tr>\n          <tr><td><span class=\"kw-def\">Fièvre prolongée</span></td><td>3 critères réunis : <span class=\"kw-bio\">température</span> <span class=\"kw-chiffre\">≥ 38,3 °C</span> à plusieurs reprises ; durée <span class=\"kw-chiffre\">≥ 3 semaines</span> ; sans cause identifiée malgré invest<span class=\"kw-chiffre\">iga</span>tions (après 3 consultations ou <span class=\"kw-chiffre\">3 jours</span> d'<span class=\"kw-alerte\">hospitalisation</span>). Définition à adapter à la clinique</td></tr>\n        </tbody>\n      </table>\n      <p><strong>Mesure de la température</strong> — la voie de référence et <span class=\"kw-clinique\">les</span> corrections diffèrent selon l'âge :</p>\n      <table >\n        <thead><tr><th>Voie</th><th>Adulte</th><th>Enfant</th></tr></thead>\n        <tbody>\n          <tr><td>Référence</td><td>Thermomètre électronique, à distance des repas, après <span class=\"kw-chiffre\">20 min de repos</span></td><td>Thermomètre électronique par <span class=\"kw-imagerie\">voie rectale</span> = référence</td></tr>\n          <tr><td>Axillaire / buccale</td><td>Majorer de <span class=\"kw-chiffre\">+ 0,5 °C</span> pour obtenir la température centrale</td><td>Buccale <span class=\"kw-chiffre\">+ 0,4 °C</span> ; axillaire <span class=\"kw-chiffre\">+ 0,5 °C</span> (sous-estimation, prise plus longue)</td></tr>\n          <tr><td>Tympanique / infrarouge</td><td>Tympanique faussée si bouchon de <span class=\"kw-clinique\">cérumen</span></td><td>Infrarouge auriculaire ou frontal : rapide mais imprécis</td></tr>\n          <tr><td>Rectale</td><td>N'est plus utilisée (risque d'<span class=\"kw-alerte\">ulcération thermométrique</span>)</td><td>Voie de référence</td></tr>\n        </tbody>\n      </table>\n      <p>Chez l'<strong>enfant</strong>, la <span class=\"kw-clinique\">fièvre</span> est définie par une <span class=\"kw-bio\">température centrale</span> <span class=\"kw-chiffre\">≥ 38 °C</span> quel que soit l'âge. Elle est dite <span class=\"kw-def\">aiguë</span> si elle évolue depuis <span class=\"kw-chiffre\">moins de 5 jours</span> chez le nourrisson, <span class=\"kw-chiffre\">moins d'une semaine</span> chez l'enfant plus âgé. Après l'âge de <span class=\"kw-chiffre\">3 mois</span>, ce sont <span class=\"kw-clinique\">les</span> infections <span class=\"kw-etio\">virales</span> qui prédominent.</p>\n      <div class=\"callout callout-warn\">⚠️ <strong>Piège :</strong> il n'existe <span class=\"kw-alerte\">aucune relation entre l'importance de la fièvre et la gravité de l'infection</span>. Une infection peut donner une <span class=\"kw-alerte\">hypothermie</span> (<span class=\"kw-clinique\">bactériémie</span> à <span class=\"kw-etio\">BGN</span>) ou ne donner aucune <span class=\"kw-clinique\">fièvre</span> sur certains terrains (<span class=\"kw-clinique\">sujet âgé</span>, <span class=\"kw-clinique\">immunodéprimé</span>).</div>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 190 — <span class=\"kw-clinique\">Fièvre</span> prolongée</em></p>","frequence":1},{"id":"147-2","rang":"A","rubrique":"Identifier une urgence","titre":"Identifier les situations d'urgence devant une fièvre aiguë chez l'adulte et chez l'enfant","contenu":"<p><strong>Chez l'adulte</strong>, <span class=\"kw-clinique\">les</span> <span class=\"kw-alerte\">signes de gravité</span> sont ceux du <span class=\"kw-alerte\">sepsis</span> et du <span class=\"kw-def\">choc septique</span>, à rechercher systématiquement : <span class=\"kw-clinique\">marbrures</span> ; <span class=\"kw-clinique\">hypotension</span> ; <span class=\"kw-clinique\">troubles de la conscience</span> ; <span class=\"kw-clinique\">oligurie</span> ; <span class=\"kw-clinique\">polypnée</span> ; <span class=\"kw-bio\">lactate</span> élevé.</p>\n      <div class=\"callout callout-warn\">⚠️ <strong>Contagiosité :</strong> tout patient fébrile est <span class=\"kw-alerte\">contagieux jusqu'à preuve du contraire</span>. Mettre en place des <span class=\"kw-ttt\">précautions Gouttelettes ou Air</span> (<span class=\"kw-def\">chambre seule</span>, masque chirurgical) en cas de signes respiratoires, de signes méningés ou d'un <span class=\"kw-alerte\">purpura fébrile</span>.</div>\n      <p><strong>Chez l'enfant</strong>, le <span class=\"kw-alerte\">risque d'infection bactérienne sévère est inversement proportionnel à l'âge</span> : <span class=\"kw-alerte\">avant 3 mois, l'examen clinique ne suffit pas</span> à éliminer une infection <span class=\"kw-etio\">bactérienne</span> sévère ; après <span class=\"kw-chiffre\">3 mois</span>, <span class=\"kw-clinique\">les</span> infections <span class=\"kw-etio\">virales</span> prédominent et l'examen clinique oriente le bilan. Rechercher les signes de <span class=\"kw-alerte\">défaillance vitale</span> :</p>\n      <table >\n        <thead><tr><th>Système</th><th>Signes de <span class=\"kw-alerte\">défaillance</span> vitale</th></tr></thead>\n        <tbody>\n          <tr><td>Neurologique</td><td><span class=\"kw-clinique\">Troubles de la conscience</span> ; <span class=\"kw-clinique\">troubles du comportement</span></td></tr>\n          <tr><td>Respiratoire</td><td><span class=\"kw-clinique\">Polypnée</span> ; <span class=\"kw-clinique\">signes de lutte</span> ; <span class=\"kw-clinique\">geignement expiratoire</span> (grunting) ; <span class=\"kw-bio\">SpO₂ basse</span></td></tr>\n          <tr><td>Hémodynamique</td><td><span class=\"kw-clinique\">Tachycardie</span> ; <span class=\"kw-clinique\">TRC allongé</span> ; pouls faible ; extrémités froides ; <span class=\"kw-clinique\">marbrures</span> ; coloration pâle ou grise ; <span class=\"kw-chiffre\">PAS abaissée</span></td></tr>\n        </tbody>\n      </table>\n      <p>Certains signes d'appel orientent vers une <strong>étiologie sévère</strong> :</p>\n      <table >\n        <thead><tr><th>Signe d'appel</th><th>Étiologie sévère à évoquer</th></tr></thead>\n        <tbody>\n          <tr><td><span class=\"kw-clinique\">Détresse respiratoire</span></td><td><span class=\"kw-etio\">Pneumonie</span>, <span class=\"kw-etio\">pleuropneumopathie</span></td></tr>\n          <tr><td><span class=\"kw-clinique\">Troubles hémodynamiques</span></td><td><span class=\"kw-def\">Sepsis</span></td></tr>\n          <tr><td><span class=\"kw-clinique\">Purpura fébrile</span></td><td>Infection à <span class=\"kw-etio\">méningocoque</span></td></tr>\n          <tr><td>Anomalie du tonus, <span class=\"kw-clinique\">trouble de la conscience</span></td><td><span class=\"kw-etio\">Méningite</span></td></tr>\n          <tr><td>Douleur à la mobilisation d'un membre</td><td><span class=\"kw-etio\">Ostéoarthrite</span></td></tr>\n          <tr><td>Selles glairo-sanglantes fébriles</td><td><span class=\"kw-etio\">Diarrhée bactérienne</span></td></tr>\n          <tr><td>Signes de <span class=\"kw-clinique\">déshydratation</span></td><td>Retentissement de la <span class=\"kw-clinique\">fièvre</span></td></tr>\n        </tbody>\n      </table>\n      <p><strong><span class=\"kw-def\">Terrain</span> à risque chez l'enfant :</strong> <span class=\"kw-alerte\">nouveau-né de moins de 3 mois</span> (particulièrement <span class=\"kw-chiffre\">moins de 6 semaines</span>) ; pathologie chronique (<span class=\"kw-clinique\">drépanocytose</span>, néphropathie, maladie systémique) ; <span class=\"kw-clinique\">immunodépression</span> ; capacités de <span class=\"kw-def\">surveillance</span> par l'entourage limitées.</p>\n      <table >\n        <thead><tr><th>Critère</th><th><span class=\"kw-clinique\">Fièvre</span> bien tolérée (<span class=\"kw-etio\">virale</span> probable)</th><th>Sévérité possible</th></tr></thead>\n        <tbody>\n          <tr><td>Faciès</td><td>Vultueux</td><td>Pâle, gris, <span class=\"kw-clinique\">cyanose péribuccale</span></td></tr>\n          <tr><td>Conscience</td><td>Normale</td><td><span class=\"kw-clinique\">Somnolence</span></td></tr>\n          <tr><td>Cri</td><td>Vigoureux</td><td>Plaintif, geignard</td></tr>\n          <tr><td>Téguments</td><td>Érythrosiques, chauds</td><td><span class=\"kw-clinique\">Marbrés</span>, froids</td></tr>\n          <tr><td>Temps de recoloration</td><td>Immédiat</td><td>Allongé <span class=\"kw-chiffre\">≥ 3 s</span></td></tr>\n        </tbody>\n      </table>\n      <div class=\"callout callout-info\">📌 <strong>Crises fébriles :</strong> elles concernent <span class=\"kw-chiffre\">2 à 5 %</span> des enfants, surviennent entre <span class=\"kw-chiffre\">6 mois et 5 ans</span> (surtout <span class=\"kw-chiffre\">1 à 3 ans</span>), et sont bénignes si le développement psychomoteur est normal. Distinguer la crise fébrile <span class=\"kw-def\">simple</span> de la crise fébrile <span class=\"kw-def\">compliquée</span>.</div>\n      <div class=\"callout callout-danger\">⚠️ Le <span class=\"kw-alerte\">purpura fulminans</span> est une <span class=\"kw-alerte\">urgence vitale absolue</span> imposant une <span class=\"kw-ttt\">antibiothérapie</span> immédiate au domicile, avant tout prélèvement.</div>\n      <p>Une fois l'<span class=\"kw-alerte\">urgence</span> identifiée, plusieurs situations imposent l'<strong><span class=\"kw-alerte\">hospitalisation</span></strong> :</p>\n      <table >\n        <thead><tr><th>Indication d'hospitalisation</th><th>Détail</th></tr></thead>\n        <tbody>\n          <tr><td><span class=\"kw-alerte\">Signes de gravité</span></td><td><span class=\"kw-def\">Sepsis</span>, <span class=\"kw-def\">choc septique</span>, <span class=\"kw-alerte\">défaillance</span> d'organe</td></tr>\n          <tr><td><span class=\"kw-def\">Terrain</span> à risque</td><td><span class=\"kw-clinique\">Femme enceinte</span> ; <span class=\"kw-alerte\">décompensation</span> de <span class=\"kw-def\">comorbidités</span> ; <span class=\"kw-clinique\">immunodépression</span></td></tr>\n          <tr><td>Prise orale impossible</td><td>Difficultés de prise orale des antibiotiques : <span class=\"kw-clinique\">troubles de déglutition</span>, <span class=\"kw-clinique\">vomissements</span></td></tr>\n          <tr><td>Échec du traitement</td><td>Absence d'amélioration à la <span class=\"kw-chiffre\">réévaluation à 48-72 h</span> d'une <span class=\"kw-ttt\">antibiothérapie</span> de 1ʳᵉ intention</td></tr>\n          <tr><td>Contexte social</td><td><span class=\"kw-clinique\">Isolement social</span>, difficultés d'observance prévisibles (SDF, éthylisme chronique)</td></tr>\n        </tbody>\n      </table>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 158 — <span class=\"kw-def\">Sepsis</span> et <span class=\"kw-def\">choc septique</span> · 151 — <span class=\"kw-etio\">Méningite</span> - <span class=\"kw-clinique\">méningoencéphalite</span></em></p>","frequence":2},{"id":"147-3","rang":"A","rubrique":"Diagnostic positif","titre":"Connaître les modalités du diagnostic étiologique devant une fièvre chez l'enfant et chez l'adulte","contenu":"<p>La démarche diagnostique repose sur un <strong>interrogatoire</strong> précis et un <strong>examen physique complet</strong>, <span class=\"kw-alerte\">patient entièrement déshabillé</span> — afin de ne pas méconnaître un <span class=\"kw-clinique\">purpura</span> ou un foyer <span class=\"kw-etio\">infectieux</span>.</p>\n      <p>L'<strong>orientation étiologique</strong> dépend largement du <span class=\"kw-def\">terrain</span> (hors immunodépression) :</p>\n      <table >\n        <thead><tr><th>Terrain</th><th>Infections à évoquer en priorité</th></tr></thead>\n        <tbody>\n          <tr><td><span class=\"kw-clinique\">Diabète</span></td><td><i><span class=\"kw-etio\">Staphylococcus aureus</span></i> (peau, parties molles, ostéite, infection du site opératoire) ; <span class=\"kw-etio\">infections urinaires</span> (vidange vésicale incomplète, <span class=\"kw-bio\">glycosurie</span>)</td></tr>\n          <tr><td><span class=\"kw-clinique\">Cirrhose</span></td><td><span class=\"kw-etio\">Pneumonie à pneumocoque</span> ; <span class=\"kw-etio\">infection spontanée du liquide d'ascite</span> (<span class=\"kw-chiffre\">80 %</span> de <span class=\"kw-etio\">BGN</span>). À noter : la <span class=\"kw-alerte\">fièvre est souvent absente chez le cirrhotique sévère infecté</span></td></tr>\n          <tr><td><span class=\"kw-clinique\">Dialyse</span></td><td>Hémodialyse : <span class=\"kw-etio\">bactériémies à staphylocoque</span> (volontiers <span class=\"kw-etio\">SARM</span>) ; dialyse péritonéale : <span class=\"kw-etio\">péritonite primaire</span> (<span class=\"kw-etio\">staphylocoque</span>, <span class=\"kw-etio\">candida</span>, BGN)</td></tr>\n          <tr><td><span class=\"kw-clinique\">Toxicomanie intraveineuse</span></td><td><i><span class=\"kw-etio\">Staphylococcus</span></i> ; <i><span class=\"kw-etio\">Pseudomonas aeruginosa</span></i> ; <i><span class=\"kw-etio\">Candida</span></i></td></tr>\n        </tbody>\n      </table>\n      <div class=\"callout callout-warn\">⚠️ <strong>Piège QRM :</strong> une <span class=\"kw-def\">fièvre n'est pas toujours d'origine infectieuse</span>. Devant une <span class=\"kw-clinique\">fièvre</span> sans foyer, toujours évoquer <span class=\"kw-clinique\">les</span> causes <span class=\"kw-etio\">non infectieuses</span> ci-dessous.</div>\n      <table >\n        <thead><tr><th>Cause non infectieuse</th><th>Étiologies à évoquer</th></tr></thead>\n        <tbody>\n          <tr><td><span class=\"kw-etio\">Syndromes d'hyperthermie</span></td><td><span class=\"kw-etio\">Coup de chaleur</span> (exercice physique en ambiance chaude) ; <span class=\"kw-clinique\">sujet âgé</span> dépendant et polymédiqué en canicule ; causes médicamenteuses (<span class=\"kw-etio\">syndrome malin des neuroleptiques</span>, <span class=\"kw-ttt\">ISRS</span>, <span class=\"kw-ttt\">antiparkinsoniens</span>) ; <span class=\"kw-clinique\">hyperthyroïdie</span> ; <span class=\"kw-clinique\">phéochromocytome</span></td></tr>\n          <tr><td><span class=\"kw-etio\">Lésionnelle</span></td><td><span class=\"kw-ttt\">Chirurgie</span> majeure ; polytraumatisme ; hématome volumineux ; <span class=\"kw-alerte\">hémorragie méningée</span> ; <span class=\"kw-alerte\">pancréatite aiguë</span></td></tr>\n          <tr><td><span class=\"kw-etio\">Néoplasique</span></td><td><span class=\"kw-clinique\">Nécrose</span> <span class=\"kw-etio\">tumorale</span> ; cancer multimétastatique ; <span class=\"kw-alerte\">hémopathie maligne aiguë</span></td></tr>\n          <tr><td><span class=\"kw-etio\">Vasculaire</span></td><td><span class=\"kw-alerte\">Accident thrombo-embolique</span> (<span class=\"kw-etio\">TVP</span>, <span class=\"kw-etio\">embolie pulmonaire</span>)</td></tr>\n          <tr><td><span class=\"kw-etio\">Inflammatoire</span></td><td><span class=\"kw-etio\">Lupus</span> en <span class=\"kw-clinique\">poussée</span> ; <span class=\"kw-clinique\">maladie de Still</span> ; <span class=\"kw-alerte\">syndrome catastrophique des antiphospholipides (CAPS)</span> ; <span class=\"kw-alerte\">DRESS syndrome</span> ; érythrodermie</td></tr>\n        </tbody>\n      </table>\n      <p>Chez l'<strong>enfant de plus de <span class=\"kw-chiffre\">3 mois</span></strong>, le <span class=\"kw-def\">diagnostic étiologique</span> est dominé par <span class=\"kw-clinique\">les</span> <span class=\"kw-etio\">viroses simples</span>, qui représentent la grande majorité des fièvres aiguës. L'<strong>interrogatoire pédiatrique</strong> recherche systématiquement :</p>\n      <table >\n        <thead><tr><th>Axe</th><th>Éléments à rechercher</th></tr></thead>\n        <tbody>\n          <tr><td>Caractéristiques de l'enfant</td><td>Âge ; <span class=\"kw-clinique\">ATCD d'infection sévère</span> ; FdR d'infection néonatale précoce ; <span class=\"kw-def\">terrain</span> à risque d'infection sévère ; <span class=\"kw-clinique\">statut vaccinal</span> +++</td></tr>\n          <tr><td>Circonstances</td><td>Notion de <span class=\"kw-clinique\">contage infectieux</span> ; <span class=\"kw-clinique\">voyage récent</span> en zone à risque ; <span class=\"kw-ttt\">antibiothérapie</span> récente ; <span class=\"kw-ttt\">chimiothérapie</span> ; <span class=\"kw-ttt\">vaccination</span> récente</td></tr>\n          <tr><td>Caractéristiques de la <span class=\"kw-clinique\">fièvre</span></td><td>Début brutal ou progressif ; signe d'appel clinique associé ; mode et voie de prise de la température</td></tr>\n          <tr><td>Examen physique</td><td>Complet, <span class=\"kw-alerte\">enfant entièrement déshabillé</span> (ne pas méconnaître un <span class=\"kw-clinique\">purpura</span>) ; recherche de signes cliniques d'orientation</td></tr>\n        </tbody>\n      </table>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 157 — <span class=\"kw-clinique\">Septicémie</span>/Bactériémie/Fongémie</em></p>","frequence":2},{"id":"147-4","rang":"A","rubrique":"Examens complémentaires","titre":"Connaître les examens complémentaires de première intention (biologie et imagerie) utiles pour le diagnostic devant une fièvre aiguë de l'enfant et de l'adulte en fonction de l'orientation clinique","contenu":"<p><strong>Chez l'adulte</strong>, l'indication des examens dépend de la durée d'<span class=\"kw-clinique\">évolution</span> : une <span class=\"kw-clinique\">fièvre</span> de <span class=\"kw-chiffre\">moins de 3 jours</span> justifie un simple bilan clinique, avec <span class=\"kw-def\">réévaluation</span> à <span class=\"kw-chiffre\">48 h</span> si elle persiste. Une <span class=\"kw-clinique\">fièvre</span> <span class=\"kw-chiffre\">≥ 3 jours</span> sans étiologie évidente conduit à un bilan paraclinique (la probabilité d'une virose simple diminue entre <span class=\"kw-chiffre\">J3</span> et J5).</p>\n      <table >\n        <thead><tr><th>Catégorie</th><th>Examens</th></tr></thead>\n        <tbody>\n          <tr><td>Systématique</td><td><span class=\"kw-bio\">NFS</span> ; <span class=\"kw-bio\">CRP</span></td></tr>\n          <tr><td>Selon le contexte</td><td><span class=\"kw-bio\">Ionogramme</span>, <span class=\"kw-bio\">urée</span>, <span class=\"kw-bio\">créatininémie</span>, <span class=\"kw-bio\">bilan hépatique</span>, <span class=\"kw-bio\">BU</span> (orientation et retentissement)</td></tr>\n          <tr><td>Si <span class=\"kw-alerte\">signes de gravité</span></td><td><span class=\"kw-bio\">TP</span>, <span class=\"kw-bio\">fibrinogène</span>, <span class=\"kw-bio\">gazométrie artérielle avec lactatémie</span></td></tr>\n          <tr><td>Microbiologie</td><td><span class=\"kw-bio\">Hémocultures</span> et prélèvements microbiologiques <span class=\"kw-alerte\">avant toute antibiothérapie</span></td></tr>\n          <tr><td>Imagerie</td><td><span class=\"kw-imagerie\">Radiographie thoracique de face</span></td></tr>\n        </tbody>\n      </table>\n      <p><strong>Chez l'enfant</strong>, en cas de situation d'<span class=\"kw-alerte\">urgence</span>, <span class=\"kw-clinique\">les</span> examens à réaliser sont :</p>\n      <table >\n        <thead><tr><th>Examen</th><th>Indication chez l'enfant</th></tr></thead>\n        <tbody>\n          <tr><td><span class=\"kw-bio\">NFS-plaquettes</span></td><td>Systématique</td></tr>\n          <tr><td><span class=\"kw-bio\">CRP</span> ou <span class=\"kw-bio\">PCT</span></td><td>Systématique</td></tr>\n          <tr><td><span class=\"kw-bio\">BU + ECBU</span></td><td>D'emblée si <span class=\"kw-chiffre\">moins de 1 mois</span></td></tr>\n          <tr><td><span class=\"kw-bio\">Hémocultures</span></td><td>Si signes de <span class=\"kw-alerte\">sepsis</span> ou nourrisson <span class=\"kw-chiffre\">de moins de 6 semaines</span></td></tr>\n          <tr><td><span class=\"kw-bio\">Ponction lombaire (LCR)</span></td><td>Si signes de <span class=\"kw-etio\">méningite</span>, ou au moindre doute chez le nourrisson <span class=\"kw-chiffre\">de moins de 6 semaines</span></td></tr>\n          <tr><td><span class=\"kw-imagerie\">Radiographie thoracique de face</span></td><td>Si signes respiratoires</td></tr>\n          <tr><td><span class=\"kw-bio\">Frottis / goutte épaisse</span></td><td>Si retour d'une zone d'endémie <span class=\"kw-etio\">palustre</span></td></tr>\n          <tr><td><span class=\"kw-bio\">TDR grippe / virologie nasale</span></td><td>Optionnel, en période épidémique</td></tr>\n        </tbody>\n      </table>\n      <p><strong>Indications du bilan chez l'enfant :</strong> <span class=\"kw-def\">terrain</span> à risque ; <span class=\"kw-alerte\">signes de gravité</span> ; <span class=\"kw-clinique\">fièvre</span> persistante (<span class=\"kw-chiffre\">nourrisson au-delà de 5 jours</span>, <span class=\"kw-chiffre\">enfant au-delà de 7 jours</span>) ; enfant de plus de <span class=\"kw-chiffre\">3 mois</span> avec <span class=\"kw-clinique\">fièvre</span> <span class=\"kw-chiffre\">de plus de 72 h</span> sans point d'appel.</p>\n      <div class=\"callout callout-info\">📌 <strong>Repères biologiques rassurants chez l'enfant</strong> (prise en charge ambulatoire possible) : <span class=\"kw-bio\">GB entre 5 000 et 15 000/mm³</span> ; <span class=\"kw-bio\">CRP &lt; 20 mg/L</span> si <span class=\"kw-clinique\">fièvre</span> évoluant depuis <span class=\"kw-chiffre\">12 à 24 h</span> ; <span class=\"kw-bio\">ECBU normal</span>.</div>","frequence":2},{"id":"147-5","rang":"A","rubrique":"Prise en charge","titre":"Connaître les indications d'antibiothérapie urgente devant une fièvre sans diagnostic précis","contenu":"<p>Dans certaines situations, une <span class=\"kw-ttt\">antibiothérapie probabiliste urgente</span> est indiquée <strong>même sans orientation étiologique</strong>, car le <span class=\"kw-alerte\">pronostic vital</span> est en jeu.</p>\n      <div class=\"callout callout-danger\">⚠️ <strong><span class=\"kw-ttt\">Antibiothérapie</span> urgente chez l'adulte</strong> indiquée devant une <span class=\"kw-clinique\">fièvre</span> sans diagnostic précis si : <span class=\"kw-alerte\">sepsis ou choc septique</span> ; <span class=\"kw-alerte\">neutropénie</span> <span class=\"kw-chiffre\">&lt; 0,5 G/L</span> ; <span class=\"kw-alerte\">asplénie</span> ; <span class=\"kw-alerte\">agammaglobulinémie</span> ; <span class=\"kw-alerte\">purpura fulminans</span>.</div>\n      <p>Le <span class=\"kw-alerte\">purpura fulminans</span> impose une <span class=\"kw-ttt\">antibiothérapie au domicile</span>, <span class=\"kw-alerte\">avant tout prélèvement</span> : <span class=\"kw-ttt\">céphalosporine de 3ᵉ génération (C3G)</span> en injection immédiate.</p>\n      <p><strong>Chez l'enfant</strong>, l'<span class=\"kw-ttt\">antibiothérapie</span> urgente est indiquée en cas de : <span class=\"kw-alerte\">sepsis ou choc septique</span> ; <span class=\"kw-alerte\">neutropénie fébrile</span> dans le cadre d'une <span class=\"kw-ttt\">chimiothérapie</span> ; <span class=\"kw-clinique\">immunodépression</span> ; <span class=\"kw-alerte\">nouveau-né de moins de 6 semaines</span>.</p>\n      <table >\n        <thead><tr><th>Situation</th><th><span class=\"kw-ttt\">Antibiothérapie</span> probabiliste</th></tr></thead>\n        <tbody>\n          <tr><td>Nouveau-né fébrile</td><td><span class=\"kw-ttt\">Amoxicilline + Gentamicine</span> par voie <span class=\"kw-ttt\">intraveineuse</span> ; <span class=\"kw-def\">réévaluation</span> à <span class=\"kw-chiffre\">48 h</span></td></tr>\n        </tbody>\n      </table>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 177 — Anti-<span class=\"kw-etio\">infectieux</span> · 158 — <span class=\"kw-def\">Sepsis</span> et <span class=\"kw-def\">choc septique</span></em></p>","frequence":0},{"id":"147-6","rang":"A","rubrique":"Prise en charge","titre":"Connaître les modalités de prise en charge symptomatique d'une fièvre de l'enfant et de l'adulte","contenu":"<p>L'objectif du traitement symptomatique est le <span class=\"kw-def\">confort</span> du patient : il ne vise <strong>ni à masquer la <span class=\"kw-clinique\">fièvre</span></strong>, <strong>ni à prévenir <span class=\"kw-clinique\">les</span> crises fébriles</strong>. Les <span class=\"kw-ttt\">antipyrétiques</span> ne sont donc <span class=\"kw-alerte\">pas systématiques</span> : ils sont indiqués si la <span class=\"kw-clinique\">fièvre</span> est mal tolérée ou sur un <span class=\"kw-def\">terrain</span> particulier (<span class=\"kw-clinique\">insuffisant cardiaque</span>, <span class=\"kw-clinique\">insuffisant respiratoire</span>, <span class=\"kw-clinique\">sujet âgé</span>).</p>\n      <p><strong>Chez l'adulte</strong>, le <span class=\"kw-ttt\">paracétamol</span> est l'antipyrétique de <span class=\"kw-chiffre\">première intention</span>. L'<span class=\"kw-ttt\">aspirine</span> et <span class=\"kw-clinique\">les</span> <span class=\"kw-ttt\">AINS</span> ne sont pas recommandés en routine. Hydratation par boissons abondantes et variées, sucrées et salées.</p>\n      <div class=\"callout callout-warn\">⚠️ Le <span class=\"kw-ttt\">paracétamol</span> est <span class=\"kw-ci\">contre-indiqué en cas d'hépatite aiguë ou d'insuffisance hépatique</span>.</div>\n      <p><strong>Chez l'enfant</strong> :</p>\n      <table >\n        <thead><tr><th>Antipyrétique</th><th>Posologie et conditions</th></tr></thead>\n        <tbody>\n          <tr><td><span class=\"kw-ttt\">Paracétamol</span></td><td><span class=\"kw-chiffre\">60 mg/kg/j</span> en 4 à 6 prises (maximum <span class=\"kw-chiffre\">80 mg/kg/j</span>) ; intervalle <span class=\"kw-chiffre\">≥ 4 h</span> entre 2 prises</td></tr>\n          <tr><td><span class=\"kw-ttt\">Ibuprofène</span></td><td><span class=\"kw-chiffre\">20 à 30 mg/kg/j</span> en 4 prises ; possible si <span class=\"kw-chiffre\">enfant de plus de 3 mois</span></td></tr>\n          <tr><td><span class=\"kw-ttt\">Kétoprofène</span></td><td>Possible si <span class=\"kw-chiffre\">enfant de plus de 6 mois</span></td></tr>\n        </tbody>\n      </table>\n      <div class=\"callout callout-danger\">⚠️ L'<span class=\"kw-ttt\">aspirine</span> et <span class=\"kw-clinique\">les</span> <span class=\"kw-ttt\">AINS</span> sont <span class=\"kw-ci\">contre-indiqués en cas de grippe ou de varicelle</span> (risque de <span class=\"kw-alerte\">syndrome de Reye</span>). Les méthodes physiques (bains froids, enveloppements humides) sont <span class=\"kw-alerte\">abandonnées</span> car inconfortables.</div>\n      <p><strong>Comment une <span class=\"kw-clinique\">fièvre</span> décompense une maladie chronique</strong> (item classiquement tombé en annale) :</p>\n      <table >\n        <thead><tr><th>Retentissement</th><th>Mécanisme</th></tr></thead>\n        <tbody>\n          <tr><td>Neurologique</td><td><span class=\"kw-clinique\">Coma</span>, <span class=\"kw-clinique\">convulsions</span>, troubles du comportement, <span class=\"kw-clinique\">délire</span></td></tr>\n          <tr><td><span class=\"kw-clinique\">Déshydratation</span></td><td><span class=\"kw-chiffre\">+ 400 mL/jour</span> de pertes par degré au-dessus de <span class=\"kw-chiffre\">37 °C</span></td></tr>\n          <tr><td>Respiratoire</td><td>Augmentation de la <span class=\"kw-clinique\">fréquence respiratoire</span> par degré</td></tr>\n          <tr><td>Cardiaque</td><td>Augmentation de la <span class=\"kw-clinique\">fréquence cardiaque de + 10 bpm</span> par degré</td></tr>\n          <tr><td><span class=\"kw-etio\">SCA</span></td><td><span class=\"kw-clinique\">Fièvre</span> et <span class=\"kw-clinique\">frissons</span> majorent <span class=\"kw-clinique\">les</span> besoins en O₂ → facteur déclenchant de <span class=\"kw-etio\">syndrome coronarien aigu</span> chez un coronarien connu ou non, surtout si <span class=\"kw-clinique\">dyspnée</span> associée</td></tr>\n        </tbody>\n      </table>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 339 — <span class=\"kw-clinique\">Syndrome coronarien</span> aiguë</em></p>","frequence":0},{"id":"147-7","rang":"B","rubrique":"Physiopathologie","titre":"Connaître les mécanismes physiopathologiques de la régulation thermique","contenu":"<p>L'<span class=\"kw-def\">homéothermie</span> est l'équilibre entre la <span class=\"kw-def\">thermogenèse</span> (production de chaleur) et la <span class=\"kw-def\">thermolyse</span> (déperdition de chaleur). Cet équilibre est réglé par un <span class=\"kw-def\">centre thermorégulateur</span> situé dans l'<span class=\"kw-def\">hypothalamus antérieur</span>.</p>\n      <p>La <span class=\"kw-clinique\">fièvre</span> correspond à une <span class=\"kw-def\">élévation du point d'équilibre hypothalamique</span> (set-point) : c'est une réponse hypothalamique à l'agression tissulaire, déclenchée par des substances <span class=\"kw-def\">pyrogènes exogènes</span> (microbiennes) et <span class=\"kw-def\">endogènes</span> (cytokines). Pour atteindre ce nouveau point d'équilibre, l'organisme remonte sa température par <span class=\"kw-clinique\">vasoconstriction</span> (diminution de la thermolyse) et <span class=\"kw-clinique\">frissons</span> (augmentation de la thermogenèse).</p>\n      <div class=\"callout callout-info\">📌 <strong><span class=\"kw-clinique\">Hyperthermie</span> ≠ <span class=\"kw-clinique\">fièvre</span>.</strong> L'<span class=\"kw-def\">hyperthermie</span> est une élévation de la température corporelle <span class=\"kw-alerte\">au-dessus du point d'équilibre hypothalamique</span>, par libération insuffisante de chaleur, <span class=\"kw-alerte\">indépendante de toute élévation du set-point</span> — donc indépendante de toute <span class=\"kw-clinique\">fièvre</span> vraie. Exemples : <span class=\"kw-etio\">coup de chaleur</span>, <span class=\"kw-etio\">syndrome malin des neuroleptiques</span>.</div>","frequence":0},{"id":"147-8","rang":"B","rubrique":"Prise en charge","titre":"Conduite à tenir devant une fièvre aiguë chez le l'enfant de moins de 28 jours","contenu":"<div class=\"callout callout-danger\">⚠️ Le <span class=\"kw-alerte\">nouveau-né de moins de 28 jours</span> (et plus largement le nourrisson de moins de <span class=\"kw-chiffre\">6 semaines</span>) est un <span class=\"kw-def\">terrain</span> à <span class=\"kw-alerte\">très haut risque d'infection bactérienne sévère</span> : la <span class=\"kw-clinique\">fièvre</span> y impose une <span class=\"kw-alerte\">hospitalisation systématique</span>, avec examens cliniques et complémentaires systématiques.</div>\n      <p>L'<strong><span class=\"kw-ttt\">antibiothérapie</span> probabiliste du nouveau-né</strong> repose sur l'association <span class=\"kw-ttt\">Amoxicilline + Gentamicine</span> par voie <span class=\"kw-ttt\">intraveineuse</span>, avec <span class=\"kw-ttt\">réévaluation à 48 h</span>.</p>\n      <p><span class=\"kw-clinique\">Les</span> <span class=\"kw-alerte\">infections néonatales bactériennes</span> du nourrisson de moins de <span class=\"kw-chiffre\">3 mois</span> sont dominées par deux germes : <i><span class=\"kw-etio\">Streptocoque B</span></i> et <i><span class=\"kw-etio\">E. coli</span></i>. On distingue selon l'âge de survenue :</p>\n      <table >\n        <thead><tr><th>Forme</th><th>Délai de survenue</th></tr></thead>\n        <tbody>\n          <tr><td><span class=\"kw-etio\">INBP</span> — infection néonatale <span class=\"kw-etio\">bactérienne</span> précoce</td><td><span class=\"kw-chiffre\">J0 à J7</span> de vie</td></tr>\n          <tr><td><span class=\"kw-etio\">INBT</span> — infection néonatale <span class=\"kw-etio\">bactérienne</span> tardive</td><td><span class=\"kw-chiffre\">J7 à 3 mois</span> post-natal</td></tr>\n        </tbody>\n      </table>\n      <p><strong>Contextes <span class=\"kw-etio\">infectieux</span> évocateurs</strong> (critères <span class=\"kw-def\">HAS 2017</span>) — la présence de ces critères chez la mère oriente vers une infection materno-fœtale :</p>\n      <table >\n        <thead><tr><th><span class=\"kw-def\">Critères majeurs</span></th></tr></thead>\n        <tbody>\n          <tr><td>Tableau évocateur de <span class=\"kw-alerte\">chorioamniotite</span></td></tr>\n          <tr><td>Jumeau atteint d'infection materno-fœtale</td></tr>\n          <tr><td><span class=\"kw-clinique\">Fièvre maternelle</span> en périnatal <span class=\"kw-chiffre\">≥ 38 °C</span></td></tr>\n          <tr><td><span class=\"kw-clinique\">Prématurité spontanée</span> <span class=\"kw-chiffre\">&lt; 35 SA</span></td></tr>\n          <tr><td><span class=\"kw-alerte\">Rupture</span> de la poche des eaux <span class=\"kw-chiffre\">≥ 18 h</span></td></tr>\n          <tr><td><span class=\"kw-alerte\">Rupture</span> prématurée des membranes <span class=\"kw-chiffre\">&lt; 37 SA</span></td></tr>\n          <tr><td><span class=\"kw-ttt\">Antibioprophylaxie</span> maternelle incomplète : ATCD d'infection materno-fœtale à <span class=\"kw-etio\">SGB</span>, portage vaginal de <span class=\"kw-etio\">SGB</span>, bactériurie à <span class=\"kw-etio\">SGB</span> pendant la <span class=\"kw-ci\">grossesse</span></td></tr>\n        </tbody>\n      </table>\n      <table >\n        <thead><tr><th><span class=\"kw-def\">Critères mineurs</span></th></tr></thead>\n        <tbody>\n          <tr><td><span class=\"kw-alerte\">Rupture</span> de la poche des eaux <span class=\"kw-chiffre\">≥ 12 h</span> (mais <span class=\"kw-chiffre\">&lt; 18 h</span>)</td></tr>\n          <tr><td><span class=\"kw-clinique\">Prématurité</span> <span class=\"kw-chiffre\">35-36 SA</span> (<span class=\"kw-chiffre\">&lt; 37 SA</span>)</td></tr>\n          <tr><td>Anomalie du rythme cardiaque fœtal ou <span class=\"kw-alerte\">asphyxie</span> fœtale inexpliquée</td></tr>\n          <tr><td>Liquide amniotique teinté ou méconial</td></tr>\n        </tbody>\n      </table>\n      <p>L'<strong><span class=\"kw-ttt\">antibioprophylaxie</span> maternelle per-partum</strong> repose sur une <span class=\"kw-ttt\">Pénicilline A</span> (<span class=\"kw-ttt\">amoxicilline</span> ou ampicilline) ou la <span class=\"kw-ttt\">Céfazoline</span>, par voie <span class=\"kw-ttt\">intraveineuse</span>, administrée <span class=\"kw-chiffre\">moins de 4 h avant la naissance</span>.</p>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 164 — Exanthème fébrile de l'enfant</em></p>","frequence":2}],"astuces":[],"strategie":{"urgence":"<p><strong><span class=\"kw-clinique\">Fièvre</span> aiguë</strong></p><ul><li>évolue depuis <span class=\"kw-chiffre\">&lt; 5 jours</span> ; étiologie le plus souvent <span class=\"kw-etio\">infectieuse</span></li><li>le <span class=\"kw-alerte\">niveau de la température ne témoigne pas à lui seul de la gravité</span> de la <span class=\"kw-clinique\">fièvre</span></li></ul><p><strong>Enfant — risque <span class=\"kw-etio\">infectieux</span></strong></p><ul><li>crainte majeure = <span class=\"kw-alerte\">infection bactérienne sévère</span> ; risque <span class=\"kw-alerte\">inversement proportionnel à l’âge</span></li><li>avant <span class=\"kw-chiffre\">3 mois</span> la clinique ne suffit pas : toute <span class=\"kw-clinique\">fièvre</span> isolée est a priori suspecte</li></ul><p><strong>Urgences vitales</strong></p><ul><li><span class=\"kw-alerte\">purpura fulminans</span> → <span class=\"kw-ttt\">antibiothérapie au domicile</span> <span class=\"kw-alerte\">avant tout prélèvement</span></li><li><span class=\"kw-alerte\">sepsis</span> / <span class=\"kw-alerte\">choc septique</span> → <span class=\"kw-ttt\">remplissage vasculaire</span> urgent</li></ul><p><strong>Délais clés</strong></p><ul><li>adulte, <span class=\"kw-clinique\">fièvre</span> <span class=\"kw-chiffre\">&lt; 3 jours</span> sans point d’appel : bilan clinique, revoir le patient à <span class=\"kw-chiffre\">48 h</span></li><li><span class=\"kw-clinique\">fièvre</span> <span class=\"kw-chiffre\">≥ 3 jours</span> sans étiologie évidente : bilan paraclinique (virose simple moins probable entre <span class=\"kw-chiffre\">J3</span>-J5)</li><li><span class=\"kw-def\">réévaluation</span> systématique à <span class=\"kw-chiffre\">48-72 h</span> d’une <span class=\"kw-ttt\">antibiothérapie</span> de 1<sup>re</sup> intention</li></ul>","hospit":"<p><strong><span class=\"kw-alerte\">Hospitalisation</span> — adulte</strong></p><ul><li><span class=\"kw-alerte\">signes de gravité</span> (<span class=\"kw-alerte\">sepsis</span>, <span class=\"kw-alerte\">défaillance</span> d’organe)</li><li><span class=\"kw-def\">terrain</span> à risque : <span class=\"kw-clinique\">femme enceinte</span>, <span class=\"kw-alerte\">décompensation</span> de <span class=\"kw-def\">comorbidités</span>, <span class=\"kw-clinique\">immunodépression</span></li><li>difficultés de prise orale des <span class=\"kw-ttt\">antibiotiques</span> (<span class=\"kw-clinique\">troubles de déglutition</span>, <span class=\"kw-clinique\">vomissements</span>)</li><li>absence d’amélioration à la <span class=\"kw-def\">réévaluation</span> à <span class=\"kw-chiffre\">48-72 h</span> d’une <span class=\"kw-ttt\">antibiothérapie</span> de 1<sup>re</sup> intention</li><li><span class=\"kw-clinique\">isolement social</span>, difficultés d’observance prévisibles (SDF, éthylisme chronique)</li></ul><p><strong><span class=\"kw-alerte\">Hospitalisation</span> — enfant</strong></p><ul><li><span class=\"kw-def\">terrain</span> à risque d’<span class=\"kw-alerte\">infection sévère</span></li><li>signes cliniques ou biologiques évocateurs d’<span class=\"kw-alerte\">infection sévère</span></li><li>pathologie nécessitant un traitement et/ou une <span class=\"kw-def\">surveillance</span> en milieu hospitalier</li><li>nourrisson <span class=\"kw-chiffre\">&lt; 6 semaines</span> : exploration et <span class=\"kw-def\">surveillance</span> en <span class=\"kw-ttt\">milieu hospitalier</span>, <span class=\"kw-ttt\">ATB probabiliste</span> souvent requise</li></ul><p><strong>Ambulatoire — enfant</strong></p><ul><li>situation la plus fréquente : <span class=\"kw-clinique\">fièvre</span> aiguë bénigne chez un enfant non à risque</li><li>évaluer la compréhension de la famille et <span class=\"kw-clinique\">les</span> possibilités de traitement symptomatique (notamment la nuit)</li><li>informer qu’une <span class=\"kw-etio\">virose</span> peut donner une <span class=\"kw-clinique\">fièvre</span> durant <span class=\"kw-chiffre\">3 voire 5 jours</span></li></ul><p><strong>Contagiosité</strong></p><ul><li>tout patient fébrile est <span class=\"kw-alerte\">contagieux jusqu’à preuve du contraire</span></li><li>si signes respiratoires, signes méningés ou <span class=\"kw-alerte\">purpura fébrile</span> → <span class=\"kw-ttt\">précautions Gouttelettes ou Air</span> (<span class=\"kw-def\">chambre seule</span>, masque chirurgical au patient)</li></ul>","redflags":"<p><strong>Règle :</strong> le <span class=\"kw-alerte\">niveau de la température ne témoigne pas à lui seul de la gravité</span> de la <span class=\"kw-clinique\">fièvre</span>.<br><strong><span class=\"kw-alerte\">Défaillance</span> vitale</strong> et <strong>signes d’infection sévère</strong> à rechercher, enfant entièrement déshabillé.</p><ul><li><span class=\"kw-alerte\">Trouble de la conscience</span> (<span class=\"kw-chiffre\">Glasgow</span>) ou du comportement : <span class=\"kw-alerte\">cri plaintif</span>, <span class=\"kw-alerte\">geignement</span></li><li><span class=\"kw-alerte\">Coloration pâle ou grise</span>, <span class=\"kw-alerte\">tachycardie</span>, <span class=\"kw-alerte\">PAS abaissée</span>, <span class=\"kw-alerte\">TRC allongé</span>, pouls faible/filant, extrémités froides</li><li><span class=\"kw-alerte\">Polypnée</span>, <span class=\"kw-alerte\">signes de lutte</span>, <span class=\"kw-alerte\">geignement expiratoire</span> (grunting), <span class=\"kw-alerte\">SpO₂ basse</span></li><li><span class=\"kw-alerte\">Purpura fébrile</span> (infection à <span class=\"kw-etio\">méningocoque</span>)</li><li><span class=\"kw-alerte\">Syndrome méningé</span> (<span class=\"kw-etio\">méningite</span>) ; anomalies du tonus et troubles de la conscience (<span class=\"kw-etio\">méningite</span>, <span class=\"kw-etio\">encéphalite</span>)</li><li><span class=\"kw-alerte\">Érythème diffus</span> (<span class=\"kw-etio\">syndrome toxinique</span>)</li><li>Douleurs à la mobilisation d’un membre (<span class=\"kw-etio\">ostéoarthrite</span>)</li><li><span class=\"kw-alerte\">Selles glairo-sanglantes</span> avec forte <span class=\"kw-clinique\">fièvre</span> (<span class=\"kw-etio\">diarrhée bactérienne</span>)</li></ul><p><strong><span class=\"kw-def\">Terrain</span> à risque</strong></p><ul><li>âge <span class=\"kw-chiffre\">&lt; 6 semaines</span> (ou <span class=\"kw-chiffre\">&lt; 3 mois</span> selon <span class=\"kw-clinique\">les</span> sources)</li><li><span class=\"kw-etio\">drépanocytose</span>, <span class=\"kw-etio\">immunosuppression</span>, <span class=\"kw-etio\">cathéter central</span>, affection chronique pulmonaire ou rénale, <span class=\"kw-etio\">maladie systémique</span></li><li>capacités de <span class=\"kw-def\">surveillance</span> de l’entourage limitées</li></ul>","principes":"<p><strong><span class=\"kw-ttt\">Antibiothérapie</span> urgente</strong> probabiliste même sans orientation étiologique si : <span class=\"kw-alerte\">sepsis</span> ou <span class=\"kw-alerte\">choc septique</span> ; <span class=\"kw-alerte\">neutropénie</span> <span class=\"kw-chiffre\">&lt; 0,5 G/L</span> ; <span class=\"kw-alerte\">asplénie</span> ; <span class=\"kw-alerte\">agammaglobulinémie</span> ; <span class=\"kw-alerte\">purpura fulminans</span> (au domicile, avant prélèvement).<br><strong>Symptomatique :</strong> objectif <span class=\"kw-def\">confort</span>, <span class=\"kw-alerte\">pas le retour à l’apyrexie</span> ni la <span class=\"kw-alerte\">prévention des crises fébriles</span> ; antipyrétiques non systématiques (si <span class=\"kw-clinique\">fièvre</span> mal tolérée ou <span class=\"kw-def\">terrain</span> particulier).</p><ul><li><span class=\"kw-ttt\">Paracétamol</span> per os = 1<sup>re</sup> intention : enfant <span class=\"kw-chiffre\">60 mg/kg/j</span> (et non par prise) en 4-6 prises de <span class=\"kw-chiffre\">15 mg/kg</span>, intervalle <span class=\"kw-chiffre\">≥ 4 h</span> ; <span class=\"kw-ci\">contre-indiqué si hépatite aiguë ou insuffisance hépatique</span></li><li><span class=\"kw-ttt\">Ibuprofène</span> (enfant <span class=\"kw-chiffre\">&gt; 3 mois</span>) : <span class=\"kw-chiffre\">20-30 mg/kg/j</span> en 4 prises, seulement si inconfort persistant malgré traitement bien conduit <span class=\"kw-chiffre\">≥ 24 h</span> ; <span class=\"kw-ttt\">kétoprofène</span> après <span class=\"kw-chiffre\">&gt; 6 mois</span></li><li><span class=\"kw-ttt\">AINS</span> <span class=\"kw-ci\">contre-indiqués en cas de varicelle</span> ; <span class=\"kw-ci\">à éviter</span> si infection pulmonaire ou ORL sévère, infection cutanée / des tissus mous, ou risque de <span class=\"kw-clinique\">déshydratation</span></li><li><span class=\"kw-ttt\">Aspirine</span> non indiquée : <span class=\"kw-ci\">risque de syndrome de Reye en cas de grippe ou de varicelle</span></li><li>Mesures physiques : donner à boire souvent (notamment la nuit), ne pas surcouvrir l’enfant, ne pas surchauffer la pièce ; <span class=\"kw-ci\">bains tièdes et enveloppements humides abandonnés</span> (source d’inconfort)</li><li>Adulte : <span class=\"kw-ttt\">paracétamol</span> ✅ ; <span class=\"kw-ttt\">hydratation</span> par boissons abondantes et variées, sucrées et salées</li><li>Nouveau-né fébrile : <span class=\"kw-ttt\">amoxicilline</span> + <span class=\"kw-ttt\">gentamicine</span> par voie <span class=\"kw-ttt\">IV</span>, <span class=\"kw-def\">réévaluation</span> à <span class=\"kw-chiffre\">48 h</span></li></ul>","suivi":"<p><strong><span class=\"kw-def\">Réévaluation</span></strong></p><ul><li>adulte, <span class=\"kw-clinique\">fièvre</span> <span class=\"kw-chiffre\">&lt; 3 jours</span> : revoir le patient à <span class=\"kw-chiffre\">48 h</span> si bilan clinique négatif</li><li><span class=\"kw-ttt\">antibiothérapie</span> de 1<sup>re</sup> intention : <span class=\"kw-def\">réévaluation</span> à <span class=\"kw-chiffre\">48-72 h</span> ; absence d’amélioration → <span class=\"kw-alerte\">hospitalisation</span></li><li><span class=\"kw-clinique\">fièvre</span> prolongée : nécessite un minimum d’invest<span class=\"kw-chiffre\">iga</span>tions pour préciser le diagnostic</li></ul><p><strong>Information de la famille (enfant ambulatoire)</strong></p><ul><li>une <span class=\"kw-etio\">virose</span> peut entraîner une <span class=\"kw-clinique\">fièvre</span> durant <span class=\"kw-chiffre\">3 voire 5 jours</span></li><li>signes devant conduire à reconsulter en <span class=\"kw-alerte\">urgence</span> : anomalies du teint, des cris, <span class=\"kw-clinique\">pleurs inconsolables</span>, <span class=\"kw-alerte\">troubles de la conscience</span>, <span class=\"kw-alerte\">troubles hémodynamiques</span>, <span class=\"kw-alerte\">détresse respiratoire</span></li><li>consignes à écrire sur l’ordonnance remise aux parents</li></ul>"},"liensGlobaux":[{"href":"https://www.pedia-univ.fr/deuxieme-cycle/referentiel/infectiologie/fievre-aigue","label":"Collège Pédiatrie — Fièvre aiguë"},{"href":"https://www.infectiologie.com/UserFiles/File/pilly-etudiant/items-edition-2023/pilly-2023-item-147.pdf","label":"Collège Pilly — Fièvre aiguë (item 147, PDF)"},{"href":"https://www.ce-mir.fr/sites/www.ce-mir.fr/files/medias/documents/44.%20Fi%C3%A8vre%20chez%20l%27immunod%C3%A9prim%C3%A9.pdf","label":"Collège CE-MIR — Fièvre chez l'immunodéprimé (PDF)"}],"arbre":{"rootId":"root","nodes":[{"id":"root","kind":"root","label":"Fièvre aiguë — recherche de signes de gravité — Patient déshabillé : sepsis, défaillance vitale, purpura fébrile ?","detail":"<h4>CAT — démarche devant une <span class=\"kw-clinique\">fièvre</span> aiguë — Enfant et adulte — gravité, puis orientation selon âge, <span class=\"kw-def\">terrain</span> et durée</h4>","branches":[{"to":"t-urgence","label":"Sepsis / choc septique, défaillance vitale OU purpura fébrile","color":"red"},{"to":"q-age","label":"Pas de signe de gravité","color":"green"}]},{"id":"t-urgence","kind":"terminal","label":"Urgence vitale → hospitalisation + ATB probabiliste urgente","color":"red","detail":"<h4>Conduite</h4><ul><li><span class=\"kw-alerte\">Hospitalisation</span> ; <span class=\"kw-ttt\">précautions Gouttelettes ou Air</span> si signes respiratoires, méningés ou <span class=\"kw-alerte\">purpura fébrile</span></li><li><span class=\"kw-alerte\">Sepsis</span> / <span class=\"kw-alerte\">choc septique</span> → <span class=\"kw-ttt\">remplissage vasculaire</span> urgent</li></ul><h4>ATB probabiliste</h4><ul><li><span class=\"kw-alerte\">Purpura fulminans</span> → <span class=\"kw-ttt\">antibiothérapie au domicile</span>, <span class=\"kw-alerte\">avant tout prélèvement</span></li><li>Indications même sans orientation : <span class=\"kw-alerte\">sepsis</span> / <span class=\"kw-alerte\">choc septique</span>, <span class=\"kw-alerte\">neutropénie</span> <span class=\"kw-chiffre\">&lt; 0,5 G/L</span>, <span class=\"kw-alerte\">asplénie</span>, <span class=\"kw-alerte\">agammaglobulinémie</span></li><li>Enfant : <span class=\"kw-alerte\">neutropénie fébrile</span> chez l’<span class=\"kw-clinique\">immunodéprimé</span></li></ul><h4>Paraclinique</h4><ul><li><span class=\"kw-bio\">NFS-plaquettes</span>, <span class=\"kw-bio\">CRP</span> ou <span class=\"kw-bio\">PCT</span>, <span class=\"kw-bio\">hémocultures</span> avant <span class=\"kw-ttt\">antibiothérapie</span>, <span class=\"kw-bio\">BU</span></li><li>Si gravité : <span class=\"kw-bio\">TP</span>, <span class=\"kw-bio\">fibrinogène</span>, <span class=\"kw-bio\">gazométrie artérielle avec lactatémie</span></li><li><span class=\"kw-bio\">Examen du LCS</span> seulement si patient stabilisé sur <span class=\"kw-clinique\">les</span> plans hémodynamique, respiratoire et neurologique</li></ul>"},{"id":"q-age","kind":"decision","label":"Nourrisson de moins de 3 mois ? — Avant 3 mois, la clinique ne suffit pas à éliminer une infection bactérienne","branches":[{"to":"q-6sem","label":"Oui — nourrisson < 3 mois","color":"amber"},{"to":"q-duree","label":"Non — enfant > 3 mois ou adulte","color":"green"}]},{"id":"q-6sem","kind":"decision","label":"Âge inférieur à<span class=\"kw-chiffre\"> 6 semaines</span> ? — Nouveau-né < <span class=\"kw-chiffre\"<span class=\"kw-chiffre\">>28</span> jours</span> = très haut risque","branches":[{"to":"t-moins6sem","label":"Oui — moins de 6 semaines (dont nouveau-né < 28 j)","color":"red"},{"to":"t-nourrisson","label":"Non — entre 6 semaines et 3 mois","color":"amber"}]},{"id":"t-moins6sem","kind":"terminal","label":"Hospitalisation + bilan systématique ± ATB probabiliste","color":"amber","detail":"<h4>Clinique</h4><ul><li>Avant <span class=\"kw-chiffre\">6 semaines</span>, toute <span class=\"kw-clinique\">fièvre</span> isolée est suspecte d’<span class=\"kw-alerte\">infection bactérienne</span> ; examens complémentaires systématiques (sauf rare exception, ex. <span class=\"kw-etio\">bronchiolite</span> récente bien tolérée sans gravité).</li></ul><h4>Paraclinique</h4><ul><li><span class=\"kw-bio\">NFS</span>, <span class=\"kw-bio\">CRP</span>, <span class=\"kw-bio\">PCT</span></li><li><span class=\"kw-bio\">BU</span> (<span class=\"kw-bio\">ECBU</span> si <span class=\"kw-chiffre\">&lt; 1 mois</span>), <span class=\"kw-bio\">hémocultures</span></li><li><span class=\"kw-bio\">Examen du LCS</span> au moindre doute (sémiologie méningée difficile à cet âge)</li></ul><h4>Traitement</h4><ul><li>Décision conditionnée par la confrontation clinico-paraclinique ; nouveau-né fébrile : <span class=\"kw-ttt\">amoxicilline</span> + <span class=\"kw-ttt\">gentamicine</span> <span class=\"kw-ttt\">IV</span>, <span class=\"kw-def\">réévaluation</span> à <span class=\"kw-chiffre\">48 h</span>.</li></ul>"},{"id":"t-nourrisson","kind":"terminal","label":"Bilan paraclinique, fièvre isolée a priori suspecte","color":"amber","detail":"<h4>Clinique</h4><ul><li>Avant <span class=\"kw-chiffre\">3 mois</span> la clinique est insuffisante : la <span class=\"kw-clinique\">fièvre</span> isolée reste a priori suspecte d’<span class=\"kw-alerte\">infection bactérienne</span>.</li></ul><h4>Paraclinique</h4><ul><li><span class=\"kw-bio\">NFS</span>, <span class=\"kw-bio\">CRP</span>, <span class=\"kw-bio\">PCT</span> ; <span class=\"kw-bio\">BU</span> (notamment si <span class=\"kw-clinique\">fièvre</span> isolée persistante <span class=\"kw-chiffre\">&gt; 48-72 h</span>)</li><li>Selon le contexte : <span class=\"kw-bio\">examen du LCS</span> si signes de <span class=\"kw-etio\">méningite</span>, <span class=\"kw-bio\">frottis-goutte épaisse</span> si retour de zone <span class=\"kw-etio\">palustre</span>, <span class=\"kw-imagerie\">RXT</span> si suspicion de <span class=\"kw-etio\">pneumonie</span></li></ul><h4>Conduite</h4><ul><li>Décision de traiter conditionnée par l’évaluation du risque <span class=\"kw-etio\">infectieux</span> (données cliniques et paracliniques).</li></ul>"},{"id":"q-duree","kind":"decision","label":"Fièvre ≥ 3 jours ou point d’appel clinique ? — Après 3 mois, les viroses prédominent largement","branches":[{"to":"t-ambu","label":"Non — fièvre < 3 j, bien tolérée, sans point d’appel","color":"green"},{"to":"t-bilan","label":"Oui — fièvre ≥ 3 j sans étiologie, ou point d’appel","color":"amber"}]},{"id":"t-ambu","kind":"terminal","label":"Ambulatoire — traitement symptomatique + réévaluation","color":"green","detail":"<h4>Clinique</h4><ul><li>Enfant <span class=\"kw-chiffre\">&gt; 3 mois</span> avec <span class=\"kw-clinique\">fièvre</span> bien tolérée → <span class=\"kw-etio\">virose</span> bénigne probable ; pas d’examen complémentaire systématique.</li></ul><h4>Traitement</h4><ul><li><span class=\"kw-ttt\">Paracétamol</span> per os : enfant <span class=\"kw-chiffre\">60 mg/kg/j</span> en 4-6 prises (intervalle <span class=\"kw-chiffre\">≥ 4 h</span>) ; adulte <span class=\"kw-ttt\">paracétamol</span> + <span class=\"kw-ttt\">hydratation</span></li><li>Objectif <span class=\"kw-def\">confort</span>, <span class=\"kw-alerte\">pas le retour à l’apyrexie</span> ; mesures physiques (boire, ne pas surcouvrir, ne pas surchauffer)</li></ul><h4><span class=\"kw-def\">Surveillance</span></h4><ul><li>Informer que la <span class=\"kw-clinique\">fièvre</span> peut durer <span class=\"kw-chiffre\">3 voire 5 jours</span> ; consignes de reconsultation écrites sur l’ordonnance ; <span class=\"kw-def\">réévaluation</span> à <span class=\"kw-chiffre\">48 h</span> si persistance.</li></ul>"},{"id":"t-bilan","kind":"terminal","label":"Bilan paraclinique ciblé selon l’orientation","color":"amber","detail":"<h4>Clinique</h4><ul><li>Probabilité d’une <span class=\"kw-etio\">virose</span> simple moindre entre <span class=\"kw-chiffre\">J3</span>-J5 ; rechercher un foyer (interrogatoire + examen complet).</li></ul><h4>Paraclinique</h4><ul><li>Adulte : <span class=\"kw-bio\">NFS</span>, <span class=\"kw-bio\">CRP</span> systématiques ; selon contexte <span class=\"kw-bio\">ionogramme</span>, <span class=\"kw-bio\">urée</span>, <span class=\"kw-bio\">créatininémie</span>, <span class=\"kw-bio\">bilan hépatique</span>, <span class=\"kw-bio\">BU</span> ; <span class=\"kw-bio\">hémocultures</span> avant <span class=\"kw-ttt\">antibiothérapie</span> ; <span class=\"kw-imagerie\">RXT de face</span></li><li>Enfant : bilan ciblé — <span class=\"kw-bio\">BU</span> si signes fonctionnels urinaires, <span class=\"kw-bio\">TDR SGA</span> si angine après l’âge de <span class=\"kw-chiffre\">3 ans</span> ; <span class=\"kw-bio\">TDR grippe</span> en période épidémique</li></ul><h4>Traitement</h4><ul><li><span class=\"kw-ttt\">Antibiothérapie</span> orientée par le foyer identifié ; <span class=\"kw-def\">réévaluation</span> à <span class=\"kw-chiffre\">48-72 h</span>.</li></ul>"}]},"cards":[{"i":"06a4c342636e","n":147,"o":"147-2","u":"Identifier une urgence","t":"Identifier les situations d'urgence devant une fièvre aiguë chez l'adulte et chez l'enfant","q":"Quels sont les signes de gravité systémiques à rechercher systématiquement chez l'adulte devant une fièvre aiguë ?","a":"<p>Chez l'adulte, les signes de gravité à rechercher devant une fièvre aiguë sont ceux du <strong>sepsis</strong> et du <strong>choc septique</strong> :</p><ul><li><strong>Marbrures</strong></li><li><strong>Hypotension</strong></li><li><strong>Troubles de la conscience</strong></li><li><strong>Oligurie</strong></li><li><strong>Polypnée</strong></li><li><strong>Lactate élevé</strong></li></ul>"},{"i":"0790d9378ffb","n":147,"o":"147-2","u":"Identifier une urgence","t":"Identifier les situations d'urgence devant une fièvre aiguë chez l'adulte et chez l'enfant","q":"Quelles sont les indications d'hospitalisation devant une fièvre aiguë chez l'adulte ou l'enfant, une fois l'urgence identifiée ?","a":"<p>Une fois l'urgence identifiée devant une fièvre aiguë, plusieurs situations imposent l'hospitalisation :</p><ul><li><strong>Signes de gravité</strong> : <strong>Sepsis</strong>, <strong>choc septique</strong>, <strong>défaillance d'organe</strong></li><li><strong>Terrain à risque</strong> : <strong>Femme enceinte</strong>, décompensation de <strong>comorbidités</strong>, <strong>immunodépression</strong></li><li><strong>Prise orale impossible</strong> : Difficultés de déglutition, <strong>vomissements</strong> compromettant la prise d'antibiotiques</li><li><strong>Échec du traitement</strong> : Absence d'amélioration à la réévaluation à <strong>48-72 heures</strong> d'une <strong>antibiothérapie de première intention</strong></li><li><strong>Contexte social</strong> : Isolement social, difficultés d'observance prévisibles (ex: SDF, éthylisme chronique)</li></ul>"},{"i":"220c5c653385","n":147,"o":"147-2","u":"Identifier une urgence","t":"Identifier les situations d'urgence devant une fièvre aiguë chez l'adulte et chez l'enfant","q":"Pourquoi l'âge est-il un facteur crucial dans l'évaluation de la gravité d'une fièvre aiguë chez l'enfant ?","a":"<p>Chez l'enfant, le risque d'infection bactérienne sévère est <strong>inversement proportionnel à l'âge</strong> :</p><ul><li><strong>Avant 3 mois</strong> : l'examen clinique seul ne suffit pas à éliminer une infection bactérienne sévère.</li><li><strong>Après 3 mois</strong> : les infections virales prédominent, et l'examen clinique est plus orientant pour le bilan.</li></ul>"},{"i":"28e78d827fea","n":147,"o":"147-2","u":"Identifier une urgence","t":"Identifier les situations d'urgence devant une fièvre aiguë chez l'adulte et chez l'enfant","q":"Quand suspecter qu'une fièvre chez l'enfant n'est PAS bien tolérée et qu'il faut envisager une sévérité possible ?","a":"<p>Une fièvre chez l'enfant doit faire suspecter une sévérité possible si l'on observe :</p><ul><li><strong>Faciès</strong> : Pâle, gris, cyanose péribuccale (au lieu de vultueux)</li><li><strong>Conscience</strong> : Somnolence (au lieu de normale)</li><li><strong>Cri</strong> : Plaintif, geignard (au lieu de vigoureux)</li><li><strong>Téguments</strong> : <strong>Marbrés</strong>, froids (au lieu d'érythrosiques et chauds)</li><li><strong>Temps de recoloration</strong> : <strong>Allongé ≥ 3 secondes</strong> (au lieu d'immédiat)</li></ul>"},{"i":"73a6f0bef07b","n":147,"o":"147-2","u":"Identifier une urgence","t":"Identifier les situations d'urgence devant une fièvre aiguë chez l'adulte et chez l'enfant","q":"Quels sont les signes de défaillance vitale à rechercher chez l'enfant fébrile ?","a":"<p>Chez l'enfant fébrile, il faut rechercher les signes de défaillance vitale selon plusieurs systèmes :</p><ul><li><strong>Neurologique</strong> : <strong>Troubles de la conscience</strong>, <strong>troubles du comportement</strong></li><li><strong>Respiratoire</strong> : <strong>Polypnée</strong>, <strong>signes de lutte</strong>, <strong>geignement expiratoire (grunting)</strong>, <strong>SpO₂ basse</strong></li><li><strong>Hémodynamique</strong> : <strong>Tachycardie</strong>, <strong>TRC allongé</strong>, <strong>pouls faible</strong>, <strong>extrémités froides</strong>, <strong>marbrures</strong>, <strong>coloration pâle ou grise</strong>, <strong>PAS abaissée</strong></li></ul>"},{"i":"c97b6d5348da","n":147,"o":"147-2","u":"Identifier une urgence","t":"Identifier les situations d'urgence devant une fièvre aiguë chez l'adulte et chez l'enfant","q":"Quels sont les signes d'appel chez l'enfant fébrile qui doivent faire évoquer une étiologie sévère spécifique ?","a":"<p>Chez l'enfant fébrile, certains signes d'appel orientent vers des étiologies sévères :</p><ul><li><strong>Détresse respiratoire</strong> : <strong>Pneumonie</strong>, <strong>pleuropneumopathie</strong></li><li><strong>Troubles hémodynamiques</strong> : <strong>Sepsis</strong></li><li><strong>Purpura fébrile</strong> : <strong>Infection à méningocoque</strong></li><li><strong>Anomalie du tonus, trouble de la conscience</strong> : <strong>Méningite</strong></li><li><strong>Douleur à la mobilisation d'un membre</strong> : <strong>Ostéoarthrite</strong></li><li><strong>Selles glairo-sanglantes fébriles</strong> : <strong>Diarrhée bactérienne</strong></li><li><strong>Signes de déshydratation</strong> : Retentissement de la fièvre</li></ul>"},{"i":"ccebe5b59f85","n":147,"o":"147-2","u":"Identifier une urgence","t":"Identifier les situations d'urgence devant une fièvre aiguë chez l'adulte et chez l'enfant","q":"Quels sont les terrains à risque chez l'enfant qui rendent une fièvre aiguë potentiellement plus grave ?","a":"<p>Chez l'enfant, les terrains à risque qui rendent une fièvre aiguë potentiellement plus grave sont :</p><ul><li><strong>Nouveau-né de moins de 3 mois</strong> (particulièrement moins de <strong>6 semaines</strong>)</li><li><strong>Pathologie chronique</strong> (comme la <strong>drépanocytose</strong>, <strong>néphropathie</strong>, <strong>maladie systémique</strong>)</li><li><strong>Immunodépression</strong></li><li><strong>Capacités de surveillance par l'entourage limitées</strong></li></ul>"},{"i":"e9c13931362e","n":147,"o":"147-2","u":"Identifier une urgence","t":"Identifier les situations d'urgence devant une fièvre aiguë chez l'adulte et chez l'enfant","q":"Quelles précautions d'hygiène un patient fébrile doit-il respecter en cas de signes respiratoires, de signes méningés ou de purpura fébrile ?","a":"<p>Devant une fièvre aiguë, tout patient fébrile est considéré comme contagieux. En présence de signes respiratoires, de signes méningés ou d'un purpura fébrile, il convient de mettre en place des <strong>précautions Gouttelettes ou Air</strong> :</p><ul><li><strong>Chambre seule</strong></li><li>Port d'un <strong>masque chirurgical</strong></li></ul>"},{"i":"32e1d6690df6","n":147,"o":"147-3","u":"Diagnostic positif","t":"Connaître les modalités du diagnostic étiologique devant une fièvre chez l'enfant et chez l'adulte","q":"Quels sont les éléments à rechercher à l'interrogatoire pédiatrique devant une fièvre aiguë chez un enfant de plus de 3 mois ?","a":"<ul><li><strong>Caractéristiques de l'enfant</strong> : âge, antécédents d'infection sévère, facteurs de risque d'infection néonatale précoce, terrain à risque d'infection sévère, <strong>statut vaccinal</strong>.</li><li><strong>Circonstances</strong> : notion de contage infectieux, voyage récent en zone à risque, antibiothérapie récente, chimiothérapie, vaccination récente.</li><li><strong>Caractéristiques de la fièvre</strong> : début brutal ou progressif, signe d'appel clinique associé, mode et voie de prise de la température.</li></ul>"},{"i":"37db8a27cf6f","n":147,"o":"147-3","u":"Diagnostic positif","t":"Connaître les modalités du diagnostic étiologique devant une fièvre chez l'enfant et chez l'adulte","q":"Quelles pathologies infectieuses doivent être évoquées en priorité chez un patient diabétique présentant une fièvre ?","a":"<p>Chez un patient diabétique, on doit évoquer en priorité les infections à <strong><em>Staphylococcus aureus</em></strong> (atteignant peau, parties molles, ostéite, infection du site opératoire) et les <strong>infections urinaires</strong>.</p>"},{"i":"3ef2705b2e4f","n":147,"o":"147-3","u":"Diagnostic positif","t":"Connaître les modalités du diagnostic étiologique devant une fièvre chez l'enfant et chez l'adulte","q":"Quelles sont les causes de fièvre non infectieuses à considérer devant une fièvre sans foyer apparent ?","a":"<ul><li><strong>Syndromes d'hyperthermie</strong> : coup de chaleur, causes médicamenteuses (syndrome malin des neuroleptiques, ISRS, antiparkinsoniens), hyperthyroïdie, phéochromocytome.</li><li><strong>Lésionnelles</strong> : chirurgie majeure, polytraumatisme, hématome volumineux, hémorragie méningée, pancréatite aiguë.</li><li><strong>Néoplasiques</strong> : nécrose tumorale, cancer multimétastatique, hémopathie maligne aiguë.</li><li><strong>Vasculaires</strong> : accident thrombo-embolique (TVP, embolie pulmonaire).</li><li><strong>Inflammatoires</strong> : lupus en poussée, maladie de Still, syndrome catastrophique des antiphospholipides (CAPS), DRESS syndrome, érythrodermie.</li></ul>"},{"i":"da7191db792f","n":147,"o":"147-3","u":"Diagnostic positif","t":"Connaître les modalités du diagnostic étiologique devant une fièvre chez l'enfant et chez l'adulte","q":"Quelles sont les infections à suspecter devant une fièvre chez un patient cirrhotique ?","a":"<p>Chez un patient cirrhotique fébrile, il faut suspecter une <strong>pneumonie à pneumocoque</strong> ou une <strong>infection spontanée du liquide d'ascite</strong> (fréquemment due à des <strong>bacilles Gram négatifs</strong>). Il est important de noter que la fièvre peut être absente chez le cirrhotique sévère infecté.</p>"},{"i":"e6a58d0b9d8e","n":147,"o":"147-3","u":"Diagnostic positif","t":"Connaître les modalités du diagnostic étiologique devant une fièvre chez l'enfant et chez l'adulte","q":"Quelle est la première étape diagnostique essentielle devant une fièvre chez l'enfant ou l'adulte ?","a":"<p>La première étape diagnostique essentielle est un <strong>interrogatoire précis</strong> et un <strong>examen physique complet</strong>, le patient étant entièrement déshabillé pour ne pas méconnaître un purpura ou un foyer infectieux.</p>"},{"i":"463fc2ac6281","n":147,"o":"147-4","u":"Examens complémentaires","t":"Connaître les examens complémentaires de première intention (biologie et imagerie) utiles pour le diagnostic devant une fièvre aiguë de l'enfant et de l'adulte en fonction de l'orientation clinique","q":"Dans quelles situations spécifiques la réalisation d'hémocultures ou d'une ponction lombaire est-elle recommandée chez l'enfant fébrile ?","a":"<ul><li><strong>Hémocultures</strong>: Si signes de <strong>sepsis</strong> ou <strong>nourrisson de moins de 6 semaines</strong>.</li><li><strong>Ponction lombaire (LCR)</strong>: Si signes de <strong>méningite</strong>, ou au moindre doute chez le <strong>nourrisson de moins de 6 semaines</strong>.</li></ul>"},{"i":"93505e4723b8","n":147,"o":"147-4","u":"Examens complémentaires","t":"Connaître les examens complémentaires de première intention (biologie et imagerie) utiles pour le diagnostic devant une fièvre aiguë de l'enfant et de l'adulte en fonction de l'orientation clinique","q":"Quels sont les examens systématiques à réaliser en urgence chez l'enfant fébrile ?","a":"<ul><li><strong>NFS-plaquettes</strong>.</li><li><strong>CRP</strong> ou <strong>PCT</strong> (Procalcitonine).</li><li><strong>BU + ECBU</strong> (Examen Cytobactériologique des Urines), d'emblée si le nourrisson a moins de <strong>1 mois</strong>.</li></ul>"},{"i":"99075f7816e5","n":147,"o":"147-4","u":"Examens complémentaires","t":"Connaître les examens complémentaires de première intention (biologie et imagerie) utiles pour le diagnostic devant une fièvre aiguë de l'enfant et de l'adulte en fonction de l'orientation clinique","q":"Quelles sont les situations générales chez l'enfant qui justifient un bilan paraclinique devant une fièvre aiguë ?","a":"<p>Un bilan paraclinique est indiqué chez l'enfant en présence des situations suivantes :</p><ul><li>Un <strong>terrain à risque</strong>.</li><li>Des <strong>signes de gravité</strong>.</li><li>Une <strong>fièvre persistante</strong> (nourrisson au-delà de <strong>5 jours</strong>, enfant au-delà de <strong>7 jours</strong>).</li><li>Un enfant de plus de 3 mois avec une fièvre de plus de <strong>72 heures sans point d'appel</strong>.</li></ul>"},{"i":"a7cdec8b126b","n":147,"o":"147-4","u":"Examens complémentaires","t":"Connaître les examens complémentaires de première intention (biologie et imagerie) utiles pour le diagnostic devant une fièvre aiguë de l'enfant et de l'adulte en fonction de l'orientation clinique","q":"Quels sont les trois repères biologiques considérés comme rassurants chez l'enfant atteint de fièvre aiguë, permettant une prise en charge ambulatoire ?","a":"<ul><li>Globules blancs (GB) entre <strong>5 000 et 15 000/mm³</strong>.</li><li>CRP <strong>inférieure à 20 mg/L</strong> si la fièvre évolue depuis 12 à 24 heures.</li><li><strong>ECBU normal</strong>.</li></ul>"},{"i":"af9cd6e0f805","n":147,"o":"147-4","u":"Examens complémentaires","t":"Connaître les examens complémentaires de première intention (biologie et imagerie) utiles pour le diagnostic devant une fièvre aiguë de l'enfant et de l'adulte en fonction de l'orientation clinique","q":"Quels sont les examens complémentaires paracliniques systématiques à envisager chez l'adulte en cas de fièvre aiguë persistante sans étiologie évidente pendant au moins 3 jours ?","a":"<ul><li><strong>NFS</strong> (Numération Formule Sanguine)</li><li><strong>CRP</strong> (C-Réactive Protéine)</li><li><strong>Hémocultures</strong> et <strong>prélèvements microbiologiques</strong> avant toute antibiothérapie</li><li>Radiographie thoracique de face (si le contexte l'indique)</li></ul>"},{"i":"bae0101358fb","n":147,"o":"147-4","u":"Examens complémentaires","t":"Connaître les examens complémentaires de première intention (biologie et imagerie) utiles pour le diagnostic devant une fièvre aiguë de l'enfant et de l'adulte en fonction de l'orientation clinique","q":"Outre les examens systématiques, quels approfondissements biologiques sont indiqués chez l'adulte en cas de fièvre aiguë persistante avec signes de gravité ou pour évaluer le retentissement ?","a":"<ul><li>Pour l'orientation diagnostique et l'évaluation du retentissement: <strong>Ionogramme sanguin</strong>, <strong>urée</strong>, <strong>créatininémie</strong>, <strong>bilan hépatique</strong>, et <strong>BU (bandelette urinaire)</strong>.</li><li>En cas de signes de gravité: <strong>TP (temps de Quick)</strong>, <strong>fibrinogène</strong>, et <strong>gazométrie artérielle avec lactatémie</strong>.</li></ul>"},{"i":"f0c3c4c3566e","n":147,"o":"147-4","u":"Examens complémentaires","t":"Connaître les examens complémentaires de première intention (biologie et imagerie) utiles pour le diagnostic devant une fièvre aiguë de l'enfant et de l'adulte en fonction de l'orientation clinique","q":"Quelle est la conduite à tenir initiale concernant l'indication des examens complémentaires pour une fièvre aiguë chez l'adulte d'une durée inférieure à 3 jours ?","a":"<p>Devant une fièvre aiguë de moins de 3 jours chez l'adulte, on réalise un simple <strong>bilan clinique</strong>. Une réévaluation est nécessaire à <strong>48 heures</strong> si la fièvre persiste.</p>"},{"i":"0bbeec118709","n":147,"o":"147-5","u":"Prise en charge","t":"Connaître les indications d'antibiothérapie urgente devant une fièvre sans diagnostic précis","q":"Dans quel contexte clinique la fièvre aiguë chez l'enfant, sans diagnostic précis, justifie-t-elle une antibiothérapie urgente et probabiliste ?","a":"<p>Chez l'enfant, une antibiothérapie probabiliste urgente est indiquée devant une fièvre sans diagnostic précis en cas de :</p><ul><li><strong>Sepsis</strong> ou <strong>choc septique</strong>.</li><li><strong>Neutropénie fébrile</strong> dans le cadre d'une chimiothérapie.</li><li><strong>Immunodépression</strong>.</li><li><strong>Nouveau-né de moins de 6 semaines</strong>.</li></ul>"},{"i":"14fa2b3037d8","n":147,"o":"147-5","u":"Prise en charge","t":"Connaître les indications d'antibiothérapie urgente devant une fièvre sans diagnostic précis","q":"Quelle est la prise en charge spécifique et le traitement urgent d'un purpura fulminans devant une fièvre sans diagnostic précis ?","a":"<p>Le purpura fulminans impose une <strong>antibiothérapie au domicile</strong>, à administrer avant tout prélèvement. L'antibiothérapie de choix est une <strong>céphalosporine de 3ᵉ génération (C3G)</strong> en injection immédiate.</p>"},{"i":"2d49e148ce87","n":147,"o":"147-5","u":"Prise en charge","t":"Connaître les indications d'antibiothérapie urgente devant une fièvre sans diagnostic précis","q":"Dans quel contexte clinique la fièvre aiguë chez l'adulte, sans diagnostic précis, justifie-t-elle une antibiothérapie urgente et probabiliste ?","a":"<p>Chez l'adulte, une antibiothérapie probabiliste urgente est indiquée devant une fièvre sans diagnostic précis en cas de :</p><ul><li><strong>Sepsis</strong> ou <strong>choc septique</strong>.</li><li><strong>Neutropénie < 0,5 G/L</strong>.</li><li><strong>Asplénie</strong>.</li><li><strong>Agammaglobulinémie</strong>.</li><li><strong>Purpura fulminans</strong>.</li></ul>"},{"i":"61d6a12da6a4","n":147,"o":"147-5","u":"Prise en charge","t":"Connaître les indications d'antibiothérapie urgente devant une fièvre sans diagnostic précis","q":"Quelle antibiothérapie probabiliste immédiate doit être instaurée chez un nouveau-né fébrile ?","a":"<p>Chez un nouveau-né fébrile, l'antibiothérapie probabiliste immédiate doit associer <strong>Amoxicilline + Gentamicine</strong> par voie intraveineuse, avec une réévaluation à 48 heures.</p>"},{"i":"0537679022f2","n":147,"o":"147-6","u":"Prise en charge","t":"Connaître les modalités de prise en charge symptomatique d'une fièvre de l'enfant et de l'adulte","q":"Quelles sont les mesures non médicamenteuses recommandées pour la prise en charge symptomatique de la fièvre ?","a":"<p>Les mesures non médicamenteuses consistent en une <strong>hydratation par boissons abondantes et variées</strong>, notamment des boissons sucrées et salées.</p>"},{"i":"8ece1fd54182","n":147,"o":"147-6","u":"Prise en charge","t":"Connaître les modalités de prise en charge symptomatique d'une fièvre de l'enfant et de l'adulte","q":"Dans quelles situations les antipyrétiques sont-ils indiqués chez l'adulte et l'enfant ?","a":"<p>Les antipyrétiques sont indiqués si la fièvre est <strong>mal tolérée</strong> ou sur un <strong>terrain particulier</strong>, comme chez un insuffisant cardiaque, un insuffisant respiratoire ou un sujet âgé.</p>"},{"i":"a2e35283adb8","n":147,"o":"147-6","u":"Prise en charge","t":"Connaître les modalités de prise en charge symptomatique d'une fièvre de l'enfant et de l'adulte","q":"Quelles sont les recommandations concernant l'aspirine et les AINS dans la prise en charge de la fièvre, en particulier chez l'enfant ?","a":"<ul><li>Chez l'adulte, l'<strong>aspirine</strong> et les <strong>AINS</strong> ne sont <strong>pas recommandés en routine</strong>.</li><li>Chez l'enfant, l'<strong>aspirine</strong> et les <strong>AINS</strong> sont <strong>contre-indiqués</strong> en cas de <strong>grippe ou de varicelle</strong> en raison du risque de <strong>syndrome de Reye</strong>.</li></ul>"},{"i":"cba7405b6c96","n":147,"o":"147-6","u":"Prise en charge","t":"Connaître les modalités de prise en charge symptomatique d'une fièvre de l'enfant et de l'adulte","q":"Comment la fièvre peut-elle décompenser une maladie chronique sur le plan neurologique et cardiovasculaire ?","a":"<ul><li><strong>Neurologique</strong> : La fièvre peut entraîner un <strong>coma</strong>, des <strong>convulsions</strong>, des troubles du comportement ou un délire.</li><li><strong>Cardiaque</strong> : La fièvre augmente la <strong>fréquence cardiaque de +10 bpm par degré</strong>. Des <strong>frissons</strong> et la fièvre peuvent majorer les besoins en O₂, déclenchant un <strong>syndrome coronarien aigu</strong> chez un coronarien connu ou non, surtout en cas de dyspnée associée.</li></ul>"},{"i":"cf096bff6ba7","n":147,"o":"147-6","u":"Prise en charge","t":"Connaître les modalités de prise en charge symptomatique d'une fièvre de l'enfant et de l'adulte","q":"Quel est l'objectif principal du traitement symptomatique de la fièvre chez l'enfant et l'adulte ?","a":"<p>L'objectif principal du traitement symptomatique de la fièvre est d'assurer le <strong>confort du patient</strong>.</p>"},{"i":"f39a52c8326f","n":147,"o":"147-6","u":"Prise en charge","t":"Connaître les modalités de prise en charge symptomatique d'une fièvre de l'enfant et de l'adulte","q":"Quel est l'antipyrétique de première intention chez l'adulte et quelles sont les contre-indications majeures du paracétamol ?","a":"<p>Chez l'adulte, le <strong>paracétamol</strong> est l'antipyrétique de première intention. Il est contre-indiqué en cas d'<strong>hépatite aiguë</strong> ou d'<strong>insuffisance hépatique</strong>.</p>"},{"i":"fd77e915e729","n":147,"o":"147-6","u":"Prise en charge","t":"Connaître les modalités de prise en charge symptomatique d'une fièvre de l'enfant et de l'adulte","q":"Quel est l'impact de la fièvre sur la déshydratation et la fonction respiratoire ?","a":"<ul><li><strong>Déshydratation</strong> : La fièvre entraîne une perte d'environ <strong>+400 mL/jour</strong> de liquides par degré au-dessus de 37 °C.</li><li><strong>Respiratoire</strong> : La fièvre provoque une <strong>augmentation de la fréquence respiratoire</strong> par degré.</li></ul>"}]};